-- ============================================================
--  Leerpret – extra quizzen voor de start van het 3de leerjaar
--  Voer uit NA schema.sql (nieuwe kolommen kind/settings/vak). Veilig om te herhalen.
-- ============================================================

-- Vak aanvullen/corrigeren voor de standaardquizzen (veilig om te herhalen)
update public.quizzes set vak='Rekenen' where (vak is null or vak='Rekenen') and title in
  ('Cirkelrekenen: optellen','Cirkelrekenen: aftrekken','Cirkelrekenen: gemengd','Getallen tot 100','Tafels van 2, 5 en 10') and school_id is null;
update public.quizzes set vak='Taal' where (vak is null or vak='Taal') and title='Taal: letters en woorden' and school_id is null;
-- Klok kijken blijft onder Varia (niet onder Rekenen)
update public.quizzes set vak='Varia' where (vak is null or vak='Rekenen') and title='Klok kijken' and school_id is null;

-- Cirkelrekenen (oefeningen worden telkens willekeurig gemaakt)
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,settings,questions)
select null,'Cirkelrekenen: optellen','Rekenen','Rekenen','➕',2,3,'circle','{"op":"+","kinds":["TE+E","TE+TE"],"bridge":"mix","count":10}'::jsonb,'[]'::jsonb
where not exists (select 1 from public.quizzes where title='Cirkelrekenen: optellen' and school_id is null);
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,settings,questions)
select null,'Cirkelrekenen: aftrekken','Rekenen','Rekenen','➖',2,3,'circle','{"op":"-","kinds":["TE+E","TE+TE"],"bridge":"mix","count":10}'::jsonb,'[]'::jsonb
where not exists (select 1 from public.quizzes where title='Cirkelrekenen: aftrekken' and school_id is null);
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,settings,questions)
select null,'Cirkelrekenen: gemengd','Rekenen','Rekenen','🔢',3,3,'circle','{"op":"mix","kinds":["TE+E","TE+TE"],"bridge":"mix","count":12}'::jsonb,'[]'::jsonb
where not exists (select 1 from public.quizzes where title='Cirkelrekenen: gemengd' and school_id is null);

-- Meerkeuzequizzen
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,questions)
select null,'Getallen tot 100','Rekenen','Rekenen','💯',3,3,'mc','[{"q":"Welk getal is 4 tientallen en 7 eenheden?","a":[{"t":"74","ok":false,"e":"Nee, dat zijn 7 tientallen en 4 eenheden. Andersom dus!"},{"t":"47","ok":true,"e":"Juist! 4 tientallen is 40, plus 7 eenheden is 47."},{"t":"11","ok":false,"e":"Nee, 4 + 7 is 11, maar tientallen zijn 10 waard. 40 + 7 = 47."}]},{"q":"Welk getal komt net na 69?","a":[{"t":"60","ok":false,"e":"Nee, 60 komt vóór 69."},{"t":"70","ok":true,"e":"Juist! Na 69 begint een nieuw tiental: 70."},{"t":"79","ok":false,"e":"Nee, dat is 10 meer. Na 69 komt 70."}]},{"q":"Welk getal is het grootste?","a":[{"t":"78","ok":false,"e":"Nee, 78 heeft 7 tientallen. Er is een getal met meer tientallen."},{"t":"87","ok":true,"e":"Juist! 87 heeft 8 tientallen, dat is meer dan 7 tientallen."},{"t":"81","ok":false,"e":"Bijna! 81 heeft ook 8 tientallen, maar 87 heeft meer eenheden."}]},{"q":"Hoeveel is 10 meer dan 56?","a":[{"t":"57","ok":false,"e":"Nee, dat is maar 1 meer. Bij 10 meer verandert het tiental."},{"t":"66","ok":true,"e":"Juist! 56 + 10 = 66. Alleen het tiental wordt één groter."},{"t":"65","ok":false,"e":"Bijna! Het tiental wordt 6, maar de eenheden blijven 6: 66."}]},{"q":"Welk getal ontbreekt: 25, 30, 35, ___, 45?","a":[{"t":"36","ok":false,"e":"Nee, we springen telkens 5 verder: 35 + 5 = ?"},{"t":"40","ok":true,"e":"Juist! We tellen met sprongen van 5: 35 + 5 = 40."},{"t":"44","ok":false,"e":"Nee, we springen met 5, niet met 9."}]},{"q":"Hoeveel is 100 − 10?","a":[{"t":"90","ok":true,"e":"Juist! 10 tientallen min 1 tiental is 9 tientallen: 90."},{"t":"99","ok":false,"e":"Nee, dat is 100 − 1. We doen 10 eraf."},{"t":"80","ok":false,"e":"Nee, dat is 100 − 20."}]},{"q":"Welk getal is even?","a":[{"t":"33","ok":false,"e":"Nee, 33 eindigt op 3. Even getallen eindigen op 0, 2, 4, 6 of 8."},{"t":"47","ok":false,"e":"Nee, 47 eindigt op 7, dat is oneven."},{"t":"58","ok":true,"e":"Juist! 58 eindigt op 8, dus het is even. Je kan het eerlijk in twee delen."}]},{"q":"Wat is 8 tientallen?","a":[{"t":"8","ok":false,"e":"Nee, 8 is 8 eenheden. Een tiental is 10 waard."},{"t":"18","ok":false,"e":"Nee, dat is 1 tiental en 8 eenheden."},{"t":"80","ok":true,"e":"Juist! 8 keer 10 is 80."}]},{"q":"Tussen welke twee tientallen ligt 63?","a":[{"t":"Tussen 50 en 60","ok":false,"e":"Nee, 63 is groter dan 60."},{"t":"Tussen 60 en 70","ok":true,"e":"Juist! 63 komt na 60 en vóór 70."},{"t":"Tussen 70 en 80","ok":false,"e":"Nee, 63 is kleiner dan 70."}]},{"q":"Hoeveel is 45 + 5?","a":[{"t":"40","ok":false,"e":"Nee, we tellen erbij, dus het getal wordt groter."},{"t":"50","ok":true,"e":"Juist! 45 + 5 = 50, precies een rond tiental."},{"t":"55","ok":false,"e":"Nee, dat is 45 + 10."}]},{"q":"Welk getal is kleiner dan 32?","a":[{"t":"41","ok":false,"e":"Nee, 41 heeft 4 tientallen, dat is meer."},{"t":"29","ok":true,"e":"Juist! 29 heeft maar 2 tientallen, dus het is kleiner dan 32."},{"t":"33","ok":false,"e":"Nee, 33 is net 1 meer dan 32."}]},{"q":"Tel verder: 92, 94, 96, ___?","a":[{"t":"97","ok":false,"e":"Nee, we springen met 2 tegelijk."},{"t":"98","ok":true,"e":"Juist! 96 + 2 = 98."},{"t":"100","ok":false,"e":"Nee, dat is 96 + 4. Eerst komt 98."}]}]'::jsonb
where not exists (select 1 from public.quizzes where title='Getallen tot 100' and school_id is null);
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,questions)
select null,'Tafels van 2, 5 en 10','Rekenen','Rekenen','✖️',2,3,'mc','[{"q":"Hoeveel is 5 × 2?","a":[{"t":"7","ok":false,"e":"Nee, dat is 5 + 2. Bij keer tel je 5 keer 2: 2 + 2 + 2 + 2 + 2."},{"t":"10","ok":true,"e":"Juist! 5 keer 2 is 10."},{"t":"12","ok":false,"e":"Nee, dat is 6 × 2."}]},{"q":"Hoeveel is 3 × 10?","a":[{"t":"13","ok":false,"e":"Nee, dat is 3 + 10. Bij de tafel van 10 zet je een 0 achter het getal."},{"t":"30","ok":true,"e":"Juist! 3 × 10 = 30."},{"t":"300","ok":false,"e":"Nee, dat is veel te veel. 3 × 10 = 30."}]},{"q":"Hoeveel is 4 × 5?","a":[{"t":"9","ok":false,"e":"Nee, dat is 4 + 5."},{"t":"20","ok":true,"e":"Juist! 5, 10, 15, 20: vier sprongen van 5."},{"t":"25","ok":false,"e":"Nee, dat is 5 × 5."}]},{"q":"Welke som hoort bij 7 × 2?","a":[{"t":"7 + 2","ok":false,"e":"Nee, 7 × 2 betekent 7 keer het getal 2."},{"t":"2 + 2 + 2 + 2 + 2 + 2 + 2","ok":true,"e":"Juist! Zeven keer 2 optellen is hetzelfde als 7 × 2 = 14."},{"t":"7 + 7 + 7","ok":false,"e":"Nee, dat is 3 × 7."}]},{"q":"Hoeveel is 10 × 10?","a":[{"t":"20","ok":false,"e":"Nee, dat is 10 + 10."},{"t":"100","ok":true,"e":"Juist! 10 × 10 = 100."},{"t":"1000","ok":false,"e":"Nee, dat is 10 × 100."}]},{"q":"Wat komt er uit: 6 × 5?","a":[{"t":"11","ok":false,"e":"Nee, dat is 6 + 5."},{"t":"30","ok":true,"e":"Juist! 5, 10, 15, 20, 25, 30."},{"t":"35","ok":false,"e":"Nee, dat is 7 × 5."}]},{"q":"Hoeveel is 8 × 2?","a":[{"t":"10","ok":false,"e":"Nee, dat is 8 + 2."},{"t":"16","ok":true,"e":"Juist! 8 × 2 = 16. Het dubbele van 8."},{"t":"18","ok":false,"e":"Nee, dat is 9 × 2."}]},{"q":"Welk getal komt NIET in de tafel van 5?","a":[{"t":"15","ok":false,"e":"Nee, 15 zit erin: 3 × 5 = 15."},{"t":"35","ok":false,"e":"Nee, 35 zit erin: 7 × 5 = 35."},{"t":"22","ok":true,"e":"Juist! Getallen in de tafel van 5 eindigen op 0 of 5. 22 hoort er niet bij."}]},{"q":"Hoeveel is 9 × 10?","a":[{"t":"19","ok":false,"e":"Nee, dat is 9 + 10."},{"t":"90","ok":true,"e":"Juist! 9 × 10 = 90."},{"t":"99","ok":false,"e":"Nee, 9 × 10 is precies 90."}]},{"q":"Er zijn 6 fietsen. Hoeveel wielen zijn dat samen?","a":[{"t":"8","ok":false,"e":"Nee, elke fiets heeft 2 wielen: 6 × 2."},{"t":"12","ok":true,"e":"Juist! 6 fietsen × 2 wielen = 12 wielen."},{"t":"6","ok":false,"e":"Nee, dat is het aantal fietsen. Elke fiets heeft 2 wielen."}]},{"q":"In elke hand zitten 5 vingers. Hoeveel vingers hebben 3 kinderen samen?","a":[{"t":"15","ok":false,"e":"Bijna! Elk kind heeft 2 handen, dus 10 vingers. 3 × 10 = ?"},{"t":"30","ok":true,"e":"Juist! 3 kinderen × 10 vingers = 30 vingers."},{"t":"8","ok":false,"e":"Nee, dat is 3 + 5. Denk aan keer!"}]},{"q":"Hoeveel is 2 × 9?","a":[{"t":"11","ok":false,"e":"Nee, dat is 2 + 9."},{"t":"18","ok":true,"e":"Juist! 2 × 9 = 18, net als 9 × 2."},{"t":"16","ok":false,"e":"Nee, dat is 2 × 8."}]}]'::jsonb
where not exists (select 1 from public.quizzes where title='Tafels van 2, 5 en 10' and school_id is null);
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,questions)
select null,'Taal: letters en woorden','Taal & spelling','Taal','🔤',3,3,'mc','[{"q":"Welke letter komt in het alfabet net na de m?","a":[{"t":"l","ok":false,"e":"Nee, de l komt vóór de m."},{"t":"n","ok":true,"e":"Juist! ... k, l, m, n, o ..."},{"t":"o","ok":false,"e":"Bijna! Eerst komt de n, dan pas de o."}]},{"q":"Welk woord is een klinker-woord? Kies het woord dat begint met een klinker.","a":[{"t":"boom","ok":false,"e":"Nee, de b is een medeklinker."},{"t":"appel","ok":true,"e":"Juist! De a is een klinker: a, e, i, o, u."},{"t":"tafel","ok":false,"e":"Nee, de t is een medeklinker."}]},{"q":"Wat is het meervoud van \"boek\"?","a":[{"t":"boekjes","ok":false,"e":"Nee, dat is een verkleinwoord. Meervoud betekent: meer dan één."},{"t":"boeken","ok":true,"e":"Juist! Eén boek, twee boeken."},{"t":"boeks","ok":false,"e":"Nee, in het Nederlands zeggen we boeken."}]},{"q":"Welk woord is juist geschreven?","a":[{"t":"Sgool","ok":false,"e":"Nee, we schrijven het met sch: school."},{"t":"School","ok":true,"e":"Juist! School schrijf je met s-c-h."},{"t":"Schoel","ok":false,"e":"Nee, het is school met een dubbele o."}]},{"q":"Hoeveel lettergrepen heeft het woord \"banaan\"?","a":[{"t":"1","ok":false,"e":"Nee, klap maar mee: ba-naan. Dat zijn er meer."},{"t":"2","ok":true,"e":"Juist! ba-naan, twee klappen."},{"t":"3","ok":false,"e":"Nee, ba-naan zijn twee lettergrepen."}]},{"q":"Welk woord moet met een hoofdletter beginnen?","a":[{"t":"hond","ok":false,"e":"Nee, een gewoon woord krijgt geen hoofdletter."},{"t":"antwerpen","ok":true,"e":"Juist! Namen van steden schrijf je met een hoofdletter: Antwerpen."},{"t":"tafel","ok":false,"e":"Nee, tafel is een gewoon woord."}]},{"q":"Wat is het tegenovergestelde van \"groot\"?","a":[{"t":"hoog","ok":false,"e":"Nee, hoog is het tegenovergestelde van laag."},{"t":"klein","ok":true,"e":"Juist! Groot en klein zijn tegenstellingen."},{"t":"dik","ok":false,"e":"Nee, dik is het tegenovergestelde van dun."}]},{"q":"Welk woord hoort niet in het rijtje: appel, peer, banaan, wortel?","a":[{"t":"appel","ok":false,"e":"Nee, een appel is fruit, net als de andere."},{"t":"banaan","ok":false,"e":"Nee, een banaan is ook fruit."},{"t":"wortel","ok":true,"e":"Juist! Een wortel is een groente, de andere drie zijn fruit."}]},{"q":"Welke letter hoor je vooraan in \"zon\"?","a":[{"t":"s","ok":false,"e":"Nee, luister goed: zzzon. Dat is een z."},{"t":"z","ok":true,"e":"Juist! Zon begint met de z."},{"t":"n","ok":false,"e":"Nee, de n hoor je achteraan."}]},{"q":"Welk woord rijmt op \"muis\"?","a":[{"t":"muur","ok":false,"e":"Nee, muur eindigt op -uur. Rijmen betekent: het einde klinkt hetzelfde."},{"t":"huis","ok":true,"e":"Juist! Muis en huis eindigen allebei op -uis."},{"t":"mus","ok":false,"e":"Nee, mus lijkt erop, maar eindigt op -us."}]},{"q":"Wat is het verkleinwoord van \"bal\"?","a":[{"t":"ballen","ok":false,"e":"Nee, dat is het meervoud."},{"t":"balletje","ok":true,"e":"Juist! Een klein balletje."},{"t":"balje","ok":false,"e":"Nee, we schrijven balletje met dubbele l en -etje."}]},{"q":"Welk woord is een werkwoord (iets wat je doet)?","a":[{"t":"stoel","ok":false,"e":"Nee, een stoel is een ding."},{"t":"lopen","ok":true,"e":"Juist! Lopen is iets wat je doet, dus een werkwoord."},{"t":"rood","ok":false,"e":"Nee, rood is een kleur."}]}]'::jsonb
where not exists (select 1 from public.quizzes where title='Taal: letters en woorden' and school_id is null);
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,questions)
select null,'Klok kijken','Klok & tijd','Varia','⏰',2,3,'mc','[{"q":"Hoeveel minuten zitten er in een uur?","a":[{"t":"30","ok":false,"e":"Nee, 30 minuten is een half uur."},{"t":"60","ok":true,"e":"Juist! Een uur is 60 minuten."},{"t":"100","ok":false,"e":"Nee, een uur heeft 60 minuten, niet 100."}]},{"q":"De kleine wijzer wijst naar de 3 en de grote wijzer naar de 12. Hoe laat is het?","a":[{"t":"Half 3","ok":false,"e":"Nee, bij half wijst de grote wijzer naar de 6."},{"t":"3 uur","ok":true,"e":"Juist! Grote wijzer op de 12 betekent: precies ... uur."},{"t":"12 uur","ok":false,"e":"Nee, de kleine wijzer zegt welk uur het is, en die staat op de 3."}]},{"q":"Hoeveel minuten is een kwartier?","a":[{"t":"10","ok":false,"e":"Nee, een kwartier is een kwart van een uur."},{"t":"15","ok":true,"e":"Juist! Een kwart van 60 minuten is 15 minuten."},{"t":"25","ok":false,"e":"Nee, een kwartier is 15 minuten."}]},{"q":"Het is half 4. Wat betekent dat?","a":[{"t":"Het is 4 uur en 30 minuten","ok":false,"e":"Nee! Half 4 betekent: het is halfweg naar 4 uur, dus nog vóór 4 uur."},{"t":"Het is 3 uur en 30 minuten","ok":true,"e":"Juist! Half 4 is 3:30. Nog een half uur en dan is het 4 uur."},{"t":"Het is 4 uur","ok":false,"e":"Nee, bij 4 uur staat de grote wijzer op de 12."}]},{"q":"Waar staat de grote wijzer bij \"half\"?","a":[{"t":"Op de 12","ok":false,"e":"Nee, op de 12 is het precies ... uur."},{"t":"Op de 6","ok":true,"e":"Juist! Bij half staat de grote wijzer onderaan, op de 6."},{"t":"Op de 3","ok":false,"e":"Nee, op de 3 is het kwart over."}]},{"q":"Het is 7 uur. Hoe laat is het over een uur?","a":[{"t":"6 uur","ok":false,"e":"Nee, over een uur is het later, niet vroeger."},{"t":"8 uur","ok":true,"e":"Juist! 7 uur + 1 uur = 8 uur."},{"t":"Half 8","ok":false,"e":"Nee, dat is over een half uur."}]},{"q":"Hoeveel uren heeft een dag?","a":[{"t":"12","ok":false,"e":"Nee, 12 is maar een halve dag. De klok gaat twee keer rond."},{"t":"24","ok":true,"e":"Juist! Een dag heeft 24 uren."},{"t":"60","ok":false,"e":"Nee, 60 is het aantal minuten in een uur."}]},{"q":"Wat is later op de dag?","a":[{"t":"8 uur ''s morgens","ok":false,"e":"Nee, ''s morgens is vroeg."},{"t":"12 uur ''s middags","ok":false,"e":"Nee, dat is het midden van de dag."},{"t":"5 uur ''s avonds","ok":true,"e":"Juist! ''s Avonds is het al laat op de dag."}]},{"q":"Hoeveel dagen heeft een week?","a":[{"t":"5","ok":false,"e":"Nee, 5 zijn de schooldagen. Het weekend telt ook mee!"},{"t":"7","ok":true,"e":"Juist! Maandag, dinsdag, woensdag, donderdag, vrijdag, zaterdag, zondag."},{"t":"10","ok":false,"e":"Nee, een week heeft 7 dagen."}]},{"q":"Welke dag komt na woensdag?","a":[{"t":"Dinsdag","ok":false,"e":"Nee, dinsdag komt vóór woensdag."},{"t":"Donderdag","ok":true,"e":"Juist! Maandag, dinsdag, woensdag, donderdag."},{"t":"Vrijdag","ok":false,"e":"Nee, eerst komt donderdag."}]}]'::jsonb
where not exists (select 1 from public.quizzes where title='Klok kijken' and school_id is null);

-- België: provincies en gewesten (voor de 2de/3de leerjaar) — enkel meerkeuzevragen, geen kaart
insert into public.quizzes (school_id,title,theme,vak,emoji,grade_min,grade_max,kind,questions)
select null,'België: provincies en gewesten','België','Wereldoriëntatie','🇧🇪',2,3,'mc','[{"q":"Hoeveel gewesten heeft België?","a":[{"t":"2","ok":false,"e":"Bijna! Er is nog een derde gewest: Brussel."},{"t":"3","ok":true,"e":"Juist! België heeft 3 gewesten: Vlaanderen, Wallonië en Brussel."},{"t":"5","ok":false,"e":"Nee, dat zijn er te veel. Het zijn er maar 3."}]},{"q":"Wat is de hoofdstad van België?","a":[{"t":"Antwerpen","ok":false,"e":"Nee, Antwerpen is wel een grote stad, maar niet de hoofdstad."},{"t":"Brussel","ok":true,"e":"Juist! Brussel is de hoofdstad van België én van Europa."},{"t":"Gent","ok":false,"e":"Nee, Gent is een mooie stad in Oost-Vlaanderen, maar geen hoofdstad."}]},{"q":"Welke taal spreekt men vooral in Vlaanderen?","a":[{"t":"Frans","ok":false,"e":"Nee, Frans spreekt men vooral in Wallonië."},{"t":"Nederlands","ok":true,"e":"Juist! In Vlaanderen spreken de meeste mensen Nederlands."},{"t":"Duits","ok":false,"e":"Nee, Duits spreekt een klein groepje mensen in het oosten van Wallonië."}]},{"q":"Welke taal spreekt men vooral in Wallonië?","a":[{"t":"Nederlands","ok":false,"e":"Nee, Nederlands spreekt men vooral in Vlaanderen."},{"t":"Frans","ok":true,"e":"Juist! In Wallonië spreken de meeste mensen Frans."},{"t":"Engels","ok":false,"e":"Nee, Engels is geen landstaal van België."}]},{"q":"Hoeveel provincies heeft België?","a":[{"t":"5","ok":false,"e":"Bijna! Dat zijn er 5 in Vlaanderen alleen. Wallonië heeft er ook 5."},{"t":"10","ok":true,"e":"Juist! België heeft 10 provincies: 5 in Vlaanderen en 5 in Wallonië. Brussel is geen provincie."},{"t":"15","ok":false,"e":"Nee, dat zijn er te veel. Het zijn er 10."}]},{"q":"Welke provincie ligt helemaal in het westen, aan de Noordzee?","a":[{"t":"West-Vlaanderen","ok":true,"e":"Juist! West-Vlaanderen ligt aan de zee. Daar vind je de Belgische kust!"},{"t":"Limburg","ok":false,"e":"Nee, Limburg ligt net aan de andere kant, helemaal in het oosten."},{"t":"Luik","ok":false,"e":"Nee, Luik ligt in het oosten van het land."}]},{"q":"Wat is de hoofdstad van Oost-Vlaanderen?","a":[{"t":"Brugge","ok":false,"e":"Nee, Brugge is de hoofdstad van West-Vlaanderen."},{"t":"Gent","ok":true,"e":"Juist! Gent is de hoofdstad van Oost-Vlaanderen, met het beroemde kasteel Gravensteen."},{"t":"Hasselt","ok":false,"e":"Nee, Hasselt is de hoofdstad van Limburg."}]},{"q":"Antwerpen is beroemd om zijn grote haven en om...?","a":[{"t":"Diamanten","ok":true,"e":"Juist! Antwerpen is wereldberoemd om zijn diamanten."},{"t":"Chocolade fabrieken","ok":false,"e":"Lekker, maar dat is niet waarom Antwerpen zo beroemd is."},{"t":"Bergen","ok":false,"e":"Nee, België heeft geen echte bergen."}]},{"q":"Welke provincie ligt helemaal in het oosten van Vlaanderen en is beroemd om zijn fruitboomgaarden?","a":[{"t":"Limburg","ok":true,"e":"Juist! Limburg heeft heel veel fruitboomgaarden."},{"t":"Antwerpen","ok":false,"e":"Nee, Antwerpen ligt meer centraal."},{"t":"Vlaams-Brabant","ok":false,"e":"Nee, Vlaams-Brabant ligt rond Brussel."}]},{"q":"In welke provincie ligt Leuven, met een van de oudste universiteiten van Europa?","a":[{"t":"Vlaams-Brabant","ok":true,"e":"Juist! Leuven ligt in Vlaams-Brabant."},{"t":"Waals-Brabant","ok":false,"e":"Nee, dat is de Franstalige provincie rond Brussel."},{"t":"Namen","ok":false,"e":"Nee, Namen ligt verder naar het zuiden."}]},{"q":"Wat is de grootste provincie van Wallonië?","a":[{"t":"Namen","ok":false,"e":"Nee, Namen is kleiner."},{"t":"Henegouwen","ok":true,"e":"Juist! Henegouwen is de grootste provincie van Wallonië. De hoofdstad is Bergen."},{"t":"Waals-Brabant","ok":false,"e":"Nee, Waals-Brabant is juist de kleinste provincie van heel België!"}]},{"q":"Welke provincie is de kleinste van heel België?","a":[{"t":"Waals-Brabant","ok":true,"e":"Juist! Waals-Brabant is de kleinste provincie van België."},{"t":"Luxemburg","ok":false,"e":"Nee, Luxemburg is net de grootste provincie van België!"},{"t":"Luik","ok":false,"e":"Nee, Luik is een van de grotere provincies."}]},{"q":"Namen, de hoofdstad van de provincie Namen, ligt op de plek waar twee rivieren samenkomen. Welke?","a":[{"t":"De Maas en de Samber","ok":true,"e":"Juist! De Maas en de Samber komen samen in Namen."},{"t":"De Schelde en de Leie","ok":false,"e":"Nee, die rivieren stromen door Gent."},{"t":"De Rijn en de Donau","ok":false,"e":"Nee, die rivieren liggen niet in België."}]},{"q":"Aan welke twee landen grenst de provincie Luik?","a":[{"t":"Frankrijk en Luxemburg","ok":false,"e":"Nee, denk aan de buren in het oosten."},{"t":"Nederland en Duitsland","ok":true,"e":"Juist! De provincie Luik grenst zowel aan Nederland als aan Duitsland."},{"t":"Nederland en Frankrijk","ok":false,"e":"Nee, dat klopt niet helemaal."}]},{"q":"De provincie Luxemburg is de grootste van België en heeft heel veel bossen. Hoe heten die bossen?","a":[{"t":"De Ardennen","ok":true,"e":"Juist! De Ardennen zijn de bekende bossen en heuvels in Luxemburg."},{"t":"Het Zoniënwoud","ok":false,"e":"Dat bos ligt bij Brussel, niet in de provincie Luxemburg."},{"t":"De Kempen","ok":false,"e":"De Kempen liggen meer in Antwerpen en Limburg."}]}]
'::jsonb
